import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }

        int totalOnes = 0;
        for (int num : a) {
            totalOnes += num;
        }

        int maxGain = -n; // Minimum possible gain is flipping all 0s to 1s and 1s to 0s
        int currentGain = 0;

        for (int i = 0; i < n; i++) {
            int gain = (a[i] == 0) ? 1 : -1;
            currentGain = Math.max(gain, currentGain + gain);
            maxGain = Math.max(maxGain, currentGain);
        }

        System.out.println(totalOnes + maxGain);
    }
}
