        for (int i = 0; i < n; i++) {
            int currentSum = 0;
            for (int j = i; j < n; j++) {
                currentSum += (1 - 2 * a[j]); // flip gain
                if (currentSum > maxGain) {
                    maxGain = currentSum;
                }
            }
        }

        System.out.println(totalOnes + maxGain);
    }
}
